window.__GUIDE_CHUNKS__.push([{"id": "11-004", "chapter_num": 11, "chapter_title": "Red Lines for Tech Workers", "chapter_file": "11-red-lines-for-tech-workers.md", "number": 4, "title": "Refuse work that powers fraud, gambling, or scams", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Turning down paying clients; no money.", "plain": "Do not build, do not maintain, apps for illegal gambling, fraud, scam operations, and do not set up their payment channels, do not unban their accounts. Writing the code that makes the crime work can make you a party to the crime, even if you never touch the victims' money.", "benefit_text": "Using a computer system with the intent to commit an offence is itself an offence under the same section that covers hacking; writing only the code is not a shield.", "sources": "Criminal Code s.342.1(c) — https://lois.justice.gc.ca/eng/acts/C-46/page-55.html", "notes": "", "urls": ["https://lois.justice.gc.ca/eng/acts/C-46/page-55.html"]}, {"id": "11-005", "chapter_num": 11, "chapter_title": "Red Lines for Tech Workers", "chapter_file": "11-red-lines-for-tech-workers.md", "number": 5, "title": "Treat code you write at work as your employer's", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Using your own time and devices for side projects; no money.", "plain": "Code, documentation, and customer lists you produce as an employee belong to your employer by default, unless your contract says otherwise. Do not copy source code to personal drives on your way out and do not reuse it at your next job. Build your open-source projects on your own time and equipment, and keep the two worlds separate.", "benefit_text": "The Copyright Act makes the employer the first owner of works created in the course of employment; taking code with you risks copyright and confidentiality claims from your former employer.", "sources": "Copyright Act s.13(3) — https://lois.justice.gc.ca/eng/acts/c-42/section-13-20121107.html", "notes": "", "urls": ["https://lois.justice.gc.ca/eng/acts/c-42/section-13-20121107.html"]}, {"id": "11-006", "chapter_num": 11, "chapter_title": "Red Lines for Tech Workers", "chapter_file": "11-red-lines-for-tech-workers.md", "number": 6, "title": "Check non-compete clauses against your province's rules", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Reading your contract carefully; no money.", "plain": "In Ontario, employers are banned from putting non-compete clauses in employment contracts, and any clause signed in breach of the ban is void — with narrow exceptions for genuine executives and business sales. Quebec still allows non-competes, but only within reasonable limits on time, territory, and activity. Know which province's rules your contract lives under before you turn down your next job.", "benefit_text": "Ontario's ban frees most employees to join competitors immediately; in Quebec an overbroad clause can be challenged as unreasonable.", "sources": "Employment Standards Act, 2000, s.67.2 (added by S.O. 2021, c. 35) — http://www.ontario.ca/laws/statute/S21035", "notes": "The Quebec rule (Civil Code art. 2089: a non-competition clause must be limited as to time, territory, and the type of work) is UNVERIFIED against the official text in this edition — direct consultation of legisquebec was blocked; see docs/verification/11-red-lines-for-tech-workers.md. Get advice before relying on it.", "urls": ["http://www.ontario.ca/laws/statute/S21035"]}, {"id": "11-007", "chapter_num": 11, "chapter_title": "Red Lines for Tech Workers", "chapter_file": "11-red-lines-for-tech-workers.md", "number": 7, "title": "Honor copyleft licences or swap the component", "money": "low", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Engineering time to replace a component, to open your code.", "plain": "If you build GPL-licensed code into your product and distribute the product, the licence requires you to distribute your changes under the same licence with source code available. Treating open code as free code is how startups end up forced to open their core work, forced to rewrite late. Check every dependency's licence before you ship.", "benefit_text": "Resolving licence conflicts early avoids forced disclosure of proprietary code or expensive rewrites after launch.", "sources": "GNU General Public License v3 — https://www.gnu.org/licenses/gpl-3.0.en.html", "notes": "", "urls": ["https://www.gnu.org/licenses/gpl-3.0.en.html"]}, {"id": "11-008", "chapter_num": 11, "chapter_title": "Red Lines for Tech Workers", "chapter_file": "11-red-lines-for-tech-workers.md", "number": 8, "title": "Collect only the personal data your app truly needs", "money": "0", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Privacy design work up front; no money.", "plain": "Collect only the personal information your app actually needs to function, get meaningful consent before collecting it, and use it only for purposes a reasonable person would consider appropriate. Write the privacy policy in plain language and keep the data secure.", "benefit_text": "Federal privacy law requires consent and limits collection to appropriate purposes; Quebec's modernized private-sector rules are stricter still. Clean data practices also survive due diligence when you sell the company.", "sources": "PIPEDA s.7 and Schedule 1 — http://laws-lois.justice.gc.ca/eng/acts/P-8.6/section-7.html ; https://lois.justice.gc.ca/eng/acts/P-8.6/FullText.html", "notes": "", "urls": ["http://laws-lois.justice.gc.ca/eng/acts/P-8.6/section-7.html", "https://lois.justice.gc.ca/eng/acts/P-8.6/FullText.html"]}, {"id": "12-001", "chapter_num": 12, "chapter_title": "Starting a Small Business", "chapter_file": "12-starting-a-business.md", "number": 1, "title": "Pick limited liability before the first big bill", "money": "low", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Federal incorporation costs $200 online and completes within one business day (2026, Corporations Canada). Quebec businesses register with the Registre des entreprises, where the name search is free. After that, the corporation keeps its own books and files its own return every year.", "plain": "As a sole proprietor, your business debts are your personal debts. As a corporation, the business is a separate legal person, so the company's debts stay with the company.", "benefit_text": "Corporations Canada (2026): online federal incorporation costs $200 and completes within one business day; stated benefits include the right to use the name across Canada, taxation separate from the owners, and limited liability. Quebec: the Registre des entreprises lets anyone check a business free of charge — its NEQ, registration status, names used, establishment addresses, directors, and ultimate beneficiaries — and check whether a business name is already taken before filing.", "sources": "https://ised-isde.canada.ca/site/corporations-canada/en/benefits-incorporating ; https://www.quebec.ca/entreprises-et-travailleurs-autonomes/obtenir-renseignements-entreprise/recherche-registre-entreprises/acceder-registre-entreprises", "notes": "Benefit graded high: a sole proprietor answers for business debts with personal assets, and a single failed lease or supplier contract can pass $50,000. Federal incorporation works in every province; a Quebec corporation also registers with the Registre des entreprises. The NEQ is the 10-digit Quebec business number issued by the register (official REQ guide). Before signing with a supplier or partner, search the register — it shows who you are actually dealing with.", "urls": ["https://ised-isde.canada.ca/site/corporations-canada/en/benefits-incorporating", "https://www.quebec.ca/entreprises-et-travailleurs-autonomes/obtenir-renseignements-entreprise/recherche-registre-entreprises/acceder-registre-entreprises"]}, {"id": "12-002", "chapter_num": 12, "chapter_title": "Starting a Small Business", "chapter_file": "12-starting-a-business.md", "number": 2, "title": "Never hand over a personal guarantee without reading what it costs", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money. The hard part is holding your ground when the lender or landlord says the loan or lease depends on your signature.", "plain": "A personal guarantee erases that wall. If the company cannot pay, the lender collects from you directly. Your spouse signing beside you puts both of your assets behind the debt.", "benefit_text": "Corporations Canada lists limited liability among the benefits of incorporating (2026). A personal guarantee waives that protection for the guaranteed debt: the creditor may collect from the guarantor personally, bypassing the company.", "sources": "https://ised-isde.canada.ca/site/corporations-canada/en/benefits-incorporating", "notes": "C-grade: the guarantee mechanics are standard commercial practice, not a cited statute. Same logic covers commercial leases — landlords routinely ask small-business owners to guarantee the rent. Benefit graded high: a guaranteed lease or loan routinely exceeds $50,000 over its term. In Quebec, family-patrimony rules add another layer to what a spouse's signature touches — UNVERIFIED at write time (see docs/verification/12-starting-a-business.md).", "urls": ["https://ised-isde.canada.ca/site/corporations-canada/en/benefits-incorporating"]}, {"id": "12-003", "chapter_num": 12, "chapter_title": "Starting a Small Business", "chapter_file": "12-starting-a-business.md", "number": 3, "title": "Sell before you build: get prepayments before any production run", "money": "low", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Tens of dollars for a sample or a simple page. The real cost is a few weeks of customer conversations before any production run. The hard part is resisting the urge to manufacture first.", "plain": "Get strangers to put money down before you manufacture anything. If nobody prepays, treat that as the market's answer.", "benefit_text": "Camuffo et al. (2020): a randomized trial of 116 Italian startups followed for about one year. Startups trained to state a hypothesis and test it against market feedback performed better, pivoted to a different idea more often, and were not more likely to quit early than the control group. The authors' explanation: the method cuts continued spending on false-positive projects — ideas that look promising but are not (2020).", "sources": "https://doi.org/10.1287/mnsc.2018.3249", "notes": "Single small study in Italy — graded B. Benefit graded mid by judgment: the source gives no dollar figure; the avoided cost is a full premature production run, typically thousands of dollars for a small business. Effect sizes were not verified from the full text (abstract only).", "urls": ["https://doi.org/10.1287/mnsc.2018.3249"]}, {"id": "12-004", "chapter_num": 12, "chapter_title": "Starting a Small Business", "chapter_file": "12-starting-a-business.md", "number": 4, "title": "Keep the company's money and your money in separate accounts", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money beyond a basic business bank account. The hard part is never paying household bills from the business account.", "plain": "The limited-liability wall only stands while the business looks like a separate person. Pay rent for your home from the company account and a court can treat the two as one.", "benefit_text": "Corporations Canada (2026): corporations are taxed separately from their owners. The CRA requires the corporation to file its own T2 return for every tax year (T4012 guide, 2026). Separate books are the paper trail that proves the separation.", "sources": "https://ised-isde.canada.ca/site/corporations-canada/en/benefits-incorporating ; https://www.canada.ca/en/revenue-agency/services/forms-publications/publications/t4012/t2-corporation-income-tax-guide-before-you-start.html", "notes": "C-grade: \"commingling can cost you the shield\" is standard legal guidance; no Canadian judgment cited here. Benefit graded mid by judgment: the exposure it protects mirrors item 1, but only partially. Practically: one business bank account, one set of books, no personal spending through the company.", "urls": ["https://ised-isde.canada.ca/site/corporations-canada/en/benefits-incorporating", "https://www.canada.ca/en/revenue-agency/services/forms-publications/publications/t4012/t2-corporation-income-tax-guide-before-you-start.html"]}, {"id": "12-005", "chapter_num": 12, "chapter_title": "Starting a Small Business", "chapter_file": "12-starting-a-business.md", "number": 5, "title": "Hiring your first employee: open a payroll account and remit on schedule", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No registration fee. Budget a few hours a month for payroll runs, or pay a bookkeeper; the remittances themselves are amounts withheld from pay, not extra cost.", "plain": "From the first paycheque, you withhold tax and premiums and send them to the government. In Quebec the money goes to two places instead of one.", "benefit_text": "CRA T4001 Employers' Guide (2026): employers open a payroll (RP) account and remit source deductions. Quebec split — QPP, QPIP, and Quebec income tax go to Revenu Québec; CPP, EI, and federal income tax go to the CRA. 2026 rates: CPP 5.95%, QPP 6.3%.", "sources": "https://www.canada.ca/content/dam/cra-arc/formspubs/pub/t4001/t4001-24e.pdf", "notes": "Benefit graded mid by judgment: missed remittances draw penalties and interest, and the amounts at stake are unquantified in the sources above — current penalty amounts are UNVERIFIED at write time (see docs/verification/12-starting-a-business.md). Workers' compensation registration is separate: WSIB in Ontario, CNESST in Quebec (see chapter 19).", "urls": ["https://www.canada.ca/content/dam/cra-arc/formspubs/pub/t4001/t4001-24e.pdf"]}, {"id": "12-006", "chapter_num": 12, "chapter_title": "Starting a Small Business", "chapter_file": "12-starting-a-business.md", "number": 6, "title": "File a T2 every year, even when the business earned nothing", "money": "0", "time": "mid", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No filing fee to the CRA. Certified software or an accountant costs money; a nil return filed yourself takes under an hour once you know the drill. The hard part is remembering the deadline in quiet years.", "plain": "The return is due every tax year — in profitable years, in loss years, and in years the company sat idle.", "benefit_text": "\"All corporations — including non-profit organizations, tax-exempt corporations, and inactive corporations — have to file a T2 return for every tax year, even if there is no tax payable.\" (CRA T2 Corporation Income Tax Guide T4012, 2026; exceptions: tax-exempt Crown corporations, Hutterite colonies, registered charities.)", "sources": "https://www.canada.ca/en/revenue-agency/services/forms-publications/publications/t4012/t2-corporation-income-tax-guide-before-you-start.html", "notes": "Quoted verbatim from the English original. Quebec corporations also file a provincial return with Revenu Québec — the form number is UNVERIFIED at write time (see docs/verification/12-starting-a-business.md). Benefit graded low: the item avoids penalties and loss of good standing; no dollar figure stated.", "urls": ["https://www.canada.ca/en/revenue-agency/services/forms-publications/publications/t4012/t2-corporation-income-tax-guide-before-you-start.html"]}, {"id": "12-007", "chapter_num": 12, "chapter_title": "Starting a Small Business", "chapter_file": "12-starting-a-business.md", "number": 7, "title": "Test a small batch before scaling production", "money": "low", "time": "mid", "willpower": "some", "benefit": "low", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "A few hundred dollars for a trial run, plus a day or two costing out yield, suppliers, storage, and shipping. The hard part is not skipping this step once the sample looks good.", "plain": "One good sample says nothing about one thousand units. Make a small batch first, measure what each unit really costs, and only then commit to volume.", "benefit_text": "Reasonable inference from the mechanism in Camuffo et al. (2020): spending decisions tested against real data reduce money sunk into false-positive projects. No independent study stands behind the checklist itself (2020).", "sources": "https://doi.org/10.1287/mnsc.2018.3249", "notes": "C by construction: the checklist is a method, not a finding. It applies whether you manufacture, import, or white-label. Importers: confirm the goods clear Canadian requirements (food, electrical, labelling) before ordering volume — the specifics are UNVERIFIED at write time (see docs/verification/12-starting-a-business.md).", "urls": ["https://doi.org/10.1287/mnsc.2018.3249"]}, {"id": "13-001", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 1, "title": "Call 911 for police, fire, and ambulance — one number covers everything", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a short call.", "plain": "In Canada one emergency number reaches police, fire, and ambulance dispatch: 911. Call only when you need help right now — a fire, a crime in progress, a person badly hurt and unable to wait. Stay on the line until the dispatcher tells you to hang up. If you dial by mistake, do not hang up; tell the dispatcher it was an accident. Texting 911 does not work in most places.", "benefit_text": "One number — 911 — reaches police, fire, and ambulance dispatchers who send help at once; calling early shortens response time when minutes decide survival.", "sources": "RCMP — tips for calling emergency services — https://www.rcmp.ca/en/bc/safety-tips/emergency-services/tips-calling-emergency-services", "notes": "Government program rule stated as fact; graded B per the adaptation contract.", "urls": ["https://www.rcmp.ca/en/bc/safety-tips/emergency-services/tips-calling-emergency-services"]}, {"id": "13-002", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 2, "title": "Call the poison centre first in any suspected poisoning", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a phone call.", "plain": "For a swallowed poison, an overdose, a chemical splash in the eyes, and a bite from an unknown creature, call the poison centre before trying home remedies. Do not make the person vomit unless the specialist tells you to. Keep the container and the label nearby so you can read the exact name to the specialist.", "benefit_text": "Canada's poison line is 1-844-764-7669 (1-844-POISON-X) and Quebec's centre is 1-800-463-5060, both open 24 hours a day, 7 days a week. Poisonings cause more than 1,500 deaths and about 8,000 hospital stays in Canada each year, so one early call is the highest-value first step.", "sources": "Health Canada — message from the Minister of Health, Poison Prevention Week 2024 — https://www.canada.ca/en/health-canada/news/2024/03/message-from-the-minister-of-health-poison-prevention-week.html", "notes": "", "urls": ["https://www.canada.ca/en/health-canada/news/2024/03/message-from-the-minister-of-health-poison-prevention-week.html"]}, {"id": "13-003", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 3, "title": "Start chest compressions at once when an adult collapses and is not breathing normally", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Nothing; your hands and your nerve.", "plain": "If an adult collapses, is unresponsive, and is not breathing normally, call 911 and start chest compressions immediately. Push hard and fast in the centre of the chest, about two inches deep, at about one hundred to one hundred twenty pushes per minute. If you are untrained, skip rescue breaths — compressions alone keep blood moving to the brain. Keep going until paramedics arrive and take over.", "benefit_text": "Bystander compressions started before paramedics arrive are linked to roughly double the chance of surviving an out-of-hospital cardiac arrest; calling 911 first makes sure advanced help is already rolling.", "sources": "Sasson C et al. (2010). Predictors of survival from out-of-hospital cardiac arrest. Circulation: Cardiovascular Quality and Outcomes. https://doi.org/10.1161/CIRCOUTCOMES.109.889576", "notes": "", "urls": ["https://doi.org/10.1161/CIRCOUTCOMES.109.889576"]}, {"id": "13-004", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 4, "title": "Act FAST on stroke signs and call 911 at once", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Nothing; a fast call.", "plain": "Face drooping, arm weakness, speech trouble — time to call 911. When one side of the face droops, one raised arm drifts down, and speech sounds slurred and strange, a stroke may be happening. Note the time the signs started and tell the dispatcher. Do not drive the person yourself, and do not give food, drink, and aspirin.", "benefit_text": "Clot-busting drugs and clot removal work only inside a short window after symptoms start, and every minute of delay kills more brain; calling 911 immediately gets the patient to a stroke-ready hospital inside that window.", "sources": "Emberson J et al. (2014). Effect of treatment delay on stroke thrombolysis. The Lancet. https://doi.org/10.1016/S0140-6736(14)60584-5", "notes": "", "urls": ["https://doi.org/10.1016/S0140-6736(14"]}, {"id": "13-005", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 5, "title": "Call 911 for chest pain that feels new and heavy", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a fast call.", "plain": "New, heavy pressure in the chest — like a weight sitting on it — lasting more than a few minutes needs 911 now. The pain can spread to the arm, neck, jaw, and back, and can come with shortness of breath, cold sweat, and nausea. Women and people with diabetes sometimes feel only breathlessness and unusual fatigue. Chew nothing and drive nowhere; wait for the ambulance.", "benefit_text": "Opening a blocked heart artery quickly limits heart muscle death; calling 911 instead of driving yourself means treatment starts in the ambulance and the hospital team is ready on arrival.", "sources": "Karkabi M et al. (2021). Door-to-balloon time and outcomes. European Heart Journal Quality of Care and Clinical Outcomes. https://doi.org/10.1093/ehjqcco/qcaa037", "notes": "", "urls": ["https://doi.org/10.1093/ehjqcco/qcaa037"]}, {"id": "13-006", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 6, "title": "Use back blows and abdominal thrusts for choking", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; your hands.", "plain": "When a choking adult cannot breathe, cannot speak, and cannot cough, act now. Lean the person forward and give five sharp back blows between the shoulder blades with the heel of your hand. If nothing comes out, stand behind the person, wrap your arms around the waist, make a fist above the belly button, and pull sharply inward and upward five times. Repeat the two sets until the object flies out and the person breathes again.", "benefit_text": "Alternating five back blows with five abdominal thrusts clears most airway blockages within seconds; doing nothing while waiting for 911 risks brain injury within minutes.", "sources": "MedlinePlus — choking first aid — https://medlineplus.gov/ency/article/000047.htm", "notes": "", "urls": ["https://medlineplus.gov/ency/article/000047.htm"]}, {"id": "13-007", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 7, "title": "Press hard on heavy bleeding; add a tourniquet high on the limb when pressure fails", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a cloth and firm hands.", "plain": "For heavy bleeding, press the wound hard with a cloth and the palm of your hand, and keep the pressure on. When blood soaks through, add more cloth on top and press harder — do not peel off the first layer. When a limb wound keeps spurting despite firm pressure, wrap a tourniquet two to three inches above the wound, tighten until the bleeding stops, and note the time. Call 911 and keep the tourniquet on until medics take over.", "benefit_text": "Firm direct pressure stops most bleeding; a properly tightened tourniquet, placed before shock sets in and left until 911 crews arrive, sharply raises survival after severe limb bleeding.", "sources": "Teixeira PGR et al. (2018). Tourniquet use in civilian trauma. Journal of the American College of Surgeons. https://doi.org/10.1016/j.jamcollsurg.2018.01.047; Kragh JF et al. (2009). Survival with emergency tourniquet use. Annals of Surgery. https://doi.org/10.1097/SLA.0b013e31818842ba", "notes": "", "urls": ["https://doi.org/10.1016/j.jamcollsurg.2018.01.047;", "https://doi.org/10.1097/SLA.0b013e31818842ba"]}, {"id": "13-008", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 8, "title": "Use the epinephrine auto-injector at the first sign of a severe allergic reaction", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "The price of the device, replaced before expiry.", "plain": "Hives spreading fast, lips and tongue swelling, throat tightening, wheezing, and dizziness after a sting, a food, and a drug mean anaphylaxis — use the auto-injector now. Jab it into the outer thigh through clothing, hold for a count of ten, then call 911. A second dose can follow after five to fifteen minutes when symptoms keep worsening.", "benefit_text": "Epinephrine in the thigh within minutes of anaphylaxis onset reverses airway swelling and collapsing blood pressure; calling 911 at the same time brings the hospital care that prevents a rebound reaction hours later.", "sources": "EAACI (2022). Guidelines on anaphylaxis. Allergy. https://doi.org/10.1111/all.15032", "notes": "", "urls": ["https://doi.org/10.1111/all.15032"]}, {"id": "13-009", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 9, "title": "Cool a burn under cool running water for twenty minutes", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Nothing; twenty minutes at the tap.", "plain": "Hold a fresh burn under cool running water for twenty minutes — a full twenty by the clock. Take off rings and tight clothing near the burn before swelling starts, unless clothing is stuck to the skin. Do not use ice, butter, toothpaste, and egg white. Cover loosely with cling film and a clean cloth after cooling, and seek care for burns larger than the palm of the hand.", "benefit_text": "Twenty minutes of cool running water limits burn depth and lowers the chance of needing a skin graft; it is the single most effective first aid for a fresh thermal burn.", "sources": "Griffin B et al. (2022). Cool running water and burn outcomes. Australasian Emergency Care. https://doi.org/10.1016/j.auec.2022.05.004", "notes": "", "urls": ["https://doi.org/10.1016/j.auec.2022.05.004"]}, {"id": "13-010", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 10, "title": "Treat sudden one-eye vision loss as a same-day emergency", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "An emergency department visit.", "plain": "When one eye suddenly goes dark like a curtain dropping while the other eye sees fine, get to an emergency department the same day. The same applies to a sudden shower of floaters with flashing lights and a dark shadow spreading across the vision. Do not wait for morning, and do not book a routine eye appointment.", "benefit_text": "A painless curtain over one eye can signal a blocked retinal artery — the eye's version of a stroke — where treatment within hours can save sight.", "sources": "Mac Grory B et al. (2021). Management of central retinal artery occlusion. Stroke. https://doi.org/10.1161/STR.0000000000000366; Rothwell PM et al. (2007). Effect of urgent treatment of transient ischaemic attack (EXPRESS study). The Lancet. https://doi.org/10.1016/S0140-6736(07)61448-2", "notes": "", "urls": ["https://doi.org/10.1016/S0140-6736(07", "https://doi.org/10.1161/STR.0000000000000366;"]}, {"id": "13-011", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 11, "title": "Rush to emergency for sudden eye pain with halos and nausea", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "An emergency department visit.", "plain": "Sudden severe eye pain with headache, rainbow halos around lights, blurred vision, and nausea with vomiting can mean acute angle closure — pressure spiking inside the eye. This is an emergency department visit now, not tomorrow. Do not use leftover eye drops, and do not try to sleep it off.", "benefit_text": "Eye pressure in acute angle closure can destroy vision within hours; emergency treatment that lowers the pressure the same day preserves sight.", "sources": "Zhou Y et al. (2022). Acute primary angle closure. Frontiers in Medicine. https://doi.org/10.3389/fmed.2022.1078237; Sung KR et al. (2023). Angle closure management. Clinical and Experimental Ophthalmology. https://doi.org/10.1111/ceo.14206", "notes": "", "urls": ["https://doi.org/10.1111/ceo.14206", "https://doi.org/10.3389/fmed.2022.1078237;"]}, {"id": "13-012", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 12, "title": "Call 911 for a thunderclap headache — the worst headache of your life", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a fast call.", "plain": "A headache that hits like a thunderclap — peak pain within seconds, the worst headache of your life — needs a 911 call and a same-day head scan. The same urgency applies when the worst headache comes with fainting, a seizure, and a stiff neck with fever. Do not take painkillers and lie down hoping it passes.", "benefit_text": "A thunderclap headache can signal bleeding around the brain; a CT scan within hours of calling 911 finds the bleed while it is still treatable.", "sources": "Perry JJ et al. (2013). Clinical decision rules for subarachnoid hemorrhage. JAMA. https://doi.org/10.1001/jama.2013.278018", "notes": "", "urls": ["https://doi.org/10.1001/jama.2013.278018"]}, {"id": "13-013", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 13, "title": "Call 911 for tearing chest pain that moves to the back", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a fast call.", "plain": "Sudden severe chest pain that feels like tearing and ripping, moving into the back and down between the shoulder blades, needs 911 at once. Fainting, a weak pulse on one side, and sudden trouble speaking alongside the pain make it more urgent. Stay still and wait for the ambulance; do not drive.", "benefit_text": "Tearing pain that migrates to the back can signal an aortic dissection, where the aorta's inner wall splits; reaching a surgical centre quickly after calling 911 is the difference between repair and rupture.", "sources": "Hagan PG et al. (2000). The International Registry of Acute Aortic Dissection (IRAD). JAMA. https://doi.org/10.1001/jama.283.7.897", "notes": "", "urls": ["https://doi.org/10.1001/jama.283.7.897"]}, {"id": "13-014", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 14, "title": "Get a same-day scan for a swollen painful leg followed by sudden breathlessness", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "An emergency department visit.", "plain": "A leg that swells, turns red and warm, and aches — especially the calf after a long flight and a long car ride — can hide a deep vein clot. When sudden shortness of breath, sharp chest pain when breathing in, and coughing blood follow, the clot may have moved to the lungs. Go to emergency the same day; do not massage the leg.", "benefit_text": "A leg clot that travels to the lungs can kill within hours; same-day ultrasound and blood thinners stop the clot from moving further.", "sources": "Goldhaber SZ et al. (1999). Acute pulmonary embolism (ICOPER). The Lancet. https://doi.org/10.1016/S0140-6736(98)07534-5", "notes": "", "urls": ["https://doi.org/10.1016/S0140-6736(98"]}, {"id": "13-015", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 15, "title": "After a head bump in an older adult, watch for slow changes and get a scan", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "An emergency department visit.", "plain": "An older adult who bumps the head — even lightly, with no cut and no loss of consciousness — can bleed slowly inside the skull over days and weeks. Watch for a headache that grows, new confusion, unusual sleepiness, weakness on one side, and repeated vomiting. Any of these means an emergency visit and a head scan the same day.", "benefit_text": "Slow bleeding under the skull after a minor bump is common past retirement age and is curable when a scan finds it early; waiting until coma sets in makes surgery far riskier.", "sources": "Dziho et al. (2025). Chronic subdural hematoma in the elderly. Brain and Spine. https://doi.org/10.1016/j.bas.2025.105893; Mathon et al. (2026). Subdural hematoma management. Pratique Neurologique. https://doi.org/10.1684/pnv.2026.1274", "notes": "", "urls": ["https://doi.org/10.1016/j.bas.2025.105893;", "https://doi.org/10.1684/pnv.2026.1274"]}, {"id": "13-016", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 16, "title": "Install carbon monoxide alarms near sleeping areas and act on the alarm", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "One alarm per floor; a few minutes to mount and test.", "plain": "Carbon monoxide has no smell and no colour; a working alarm is the only warning you get. Ontario law requires CO alarms near sleeping areas in homes with a fuel-burning appliance, a fireplace, and an attached garage. When the alarm sounds, get everyone outside into fresh air at once and call 911 from outside. Do not open windows first, and do not go back inside for pets and belongings.", "benefit_text": "Ontario's Hawkins-Gignac Act (in force since 2014) requires CO alarms beside sleeping areas in homes with fuel-burning appliances, fireplaces, and attached garages; when the alarm sounds, leaving immediately and calling 911 from outside avoids the confusion-to-collapse sequence of CO poisoning.", "sources": "Hawkins-Gignac Act (Carbon Monoxide Safety), 2013, S.O. 2013, c. 14 — https://www.ontario.ca/laws/statute/s13014; U.S. CPSC — carbon monoxide information center — https://www.cpsc.gov/Safety-Education/Safety-Education-Centers/Carbon-Monoxide-Information-Center", "notes": "", "urls": ["https://www.cpsc.gov/Safety-Education/Safety-Education-Centers/Carbon-Monoxide-Information-Center", "https://www.ontario.ca/laws/statute/s13014;"]}, {"id": "13-017", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 17, "title": "During a seizure, protect from injury and time it — never put anything in the mouth", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; calm hands and a phone timer.", "plain": "When someone seizes, ease the person to the floor, move hard and sharp objects away, and place something soft under the head. Turn the person onto the side once the shaking slows so fluids drain out. Time the seizure with your phone. Never put fingers, spoons, and wallets in the mouth — the person will not swallow the tongue. Call 911 when the seizure lasts past five minutes, when another follows at once, and when the person stays unconscious after it ends.", "benefit_text": "Most seizures end on their own within a couple of minutes and need no drugs; the side position prevents choking, and calling 911 for seizures that pass five minutes brings the medication that stops status epilepticus.", "sources": "U.S. CDC — first aid for seizures — http://cdc.gov/epilepsy/first-aid-for-seizures/", "notes": "", "urls": ["http://cdc.gov/epilepsy/first-aid-for-seizures/"]}, {"id": "13-018", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 18, "title": "Treat low blood sugar with fast sugar and recheck after fifteen minutes", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Glucose tablets and juice kept on hand.", "plain": "A person with diabetes who turns shaky, sweaty, confused, and pale may have low blood sugar. Give about fifteen grams of fast sugar — four glucose tablets and half a cup of juice — then wait fifteen minutes and recheck. When still low, repeat. When the person cannot swallow and loses consciousness, pour nothing into the mouth; call 911.", "benefit_text": "Fifteen grams of fast-acting sugar raises blood glucose within fifteen minutes and reverses most mild episodes; calling 911 when the person cannot swallow brings the glucagon and IV sugar that prevent seizure and coma.", "sources": "American Diabetes Association (2025). Standards of Care — hypoglycemia. Diabetes Care. https://doi.org/10.2337/dc25-S006", "notes": "", "urls": ["https://doi.org/10.2337/dc25-S006"]}, {"id": "13-019", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 19, "title": "Flush chemical splashes with lots of water and strip contaminated clothing", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "A long rinse at the tap and a change of clothes.", "plain": "Chemicals splashed in the eyes need immediate flushing with large amounts of clean water, holding the lids open, for a prolonged rinse. For skin splashes, take off the soaked clothing at once and flush the skin with running water. Bring the chemical container and the label to the emergency department.", "benefit_text": "Prolonged water irrigation dilutes corrosive chemicals and limits tissue damage; removing soaked clothing stops the burn from continuing under the fabric.", "sources": "NIOSH — first aid for chemical exposures — http://www.cdc.gov/niosh/npg/firstaid.html", "notes": "", "urls": ["http://www.cdc.gov/niosh/npg/firstaid.html"]}, {"id": "13-020", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 20, "title": "After an electric shock, break the contact safely and call 911", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a clear head and a dry wooden handle.", "plain": "When someone is being shocked, do not touch the person directly. Switch off the power at the breaker and the switch first. When you cannot cut the power, push the person away from the source with a dry wooden broom handle and dry rope — never with metal and never with wet hands. Call 911 even when the person looks fine; heart rhythm problems can appear later.", "benefit_text": "Cutting the power before touching the victim prevents a second casualty; calling 911 after any mains-voltage shock catches the delayed heart rhythm problems that can kill hours later.", "sources": "U.S. CDC — what to do to protect yourself from electrical hazards — https://www.cdc.gov/natural-disasters/response/what-to-do-protect-yourself-from-electrical-hazards.html", "notes": "", "urls": ["https://www.cdc.gov/natural-disasters/response/what-to-do-protect-yourself-from-electrical-hazards.html"]}, {"id": "13-021", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 21, "title": "Cool a heat-stroke victim fast and call 911", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; cold water and shade.", "plain": "Hot red dry skin, confusion, fainting, and a soaring temperature after exertion in the heat mean heat stroke — call 911 at once. Move the person to shade, strip excess clothing, and cool aggressively: cold water on the skin, fanning, and ice packs to the neck, armpits, and groin. Give small sips of cool water only when fully alert.", "benefit_text": "In heat stroke the body's cooling has failed and organs overheat; aggressive cooling started before 911 crews arrive is the main factor that separates survival from death.", "sources": "Wilderness Medical Society (2024). Clinical practice guidelines for heat illness. Wilderness and Environmental Medicine. https://doi.org/10.1177/10806032241227924; U.S. National Weather Service — heat illness safety — https://www.weather.gov/safety/heat-illness", "notes": "", "urls": ["https://doi.org/10.1177/10806032241227924;", "https://www.weather.gov/safety/heat-illness"]}, {"id": "13-022", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 22, "title": "Warm a hypothermia victim gently and call 911", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; dry blankets and shelter from wind.", "plain": "Uncontrollable shivering that stops, clumsiness, confusion, and drowsiness in the cold mean hypothermia — call 911. Get the person out of the wind and out of wet clothing, wrap in dry blankets with a vapour barrier, and give warm sweet drinks only when fully alert. Handle gently: no rubbing of the limbs and no hot water.", "benefit_text": "Gentle rewarming after calling 911 prevents the heart rhythm collapse that rough handling can trigger in a severely cold victim.", "sources": "Wilderness Medical Society (2019). Clinical practice guidelines for hypothermia. Wilderness and Environmental Medicine. https://doi.org/10.1016/j.wem.2019.10.002; U.S. National Weather Service — cold safety — https://www.weather.gov/safety/cold-during", "notes": "", "urls": ["https://doi.org/10.1016/j.wem.2019.10.002;", "https://www.weather.gov/safety/cold-during"]}, {"id": "13-023", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 23, "title": "Get out of a house fire fast and stay out", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a practiced escape route.", "plain": "When fire breaks out, get everyone out through the nearest safe route and close doors behind you to slow the smoke. Crawl low under smoke, feel doors with the back of your hand, and use stairs — never the elevator. Once outside, call 911 from a safe distance and stay out; nothing inside is worth a second trip.", "benefit_text": "Most fire deaths come from smoke inhalation within minutes, not burns; leaving immediately and calling 911 from outside keeps you out of the smoke layer that kills.", "sources": "FEMA — home fires — https://www.ready.gov/home-fires", "notes": "", "urls": ["https://www.ready.gov/home-fires"]}, {"id": "13-024", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 24, "title": "For a drowning person, reach and throw — do not go in", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a pole, a rope, and a cool head.", "plain": "A drowning person cannot call for help; reach the person with a pole, a branch, and a towel from the shore and the dock, and throw a rope and a life ring when reaching fails. Call 911 as soon as someone else can take over the rescue attempt. Enter the water yourself only when you are a trained rescuer; a panicking swimmer can pull an untrained rescuer under.", "benefit_text": "Reach-and-throw rescue keeps the rescuer out of the water, where most would-be rescuers drown; calling 911 early starts the clock on advanced care for the victim.", "sources": "Lifesaving Society of Canada — drowning rescue guidance — https://www.lifesaving.org/public/download/documents/53934", "notes": "", "urls": ["https://www.lifesaving.org/public/download/documents/53934"]}, {"id": "13-025", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 25, "title": "Remove a tick with fine tweezers and watch the bite", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "A pair of fine-tipped tweezers; watching the bite for a month.", "plain": "Grasp a tick with fine-tipped tweezers as close to the skin as possible and pull straight up with steady pressure — no twisting and no squeezing of the body. Clean the bite with soap and water, save the tick in a dated container, and watch the skin for a spreading bull's-eye rash over the next month. Call your provincial health line for advice on preventive treatment.", "benefit_text": "Proper removal within hours lowers the chance of Lyme disease transmission; a saved tick lets the lab identify the species and guide preventive antibiotics.", "sources": "Parks Canada — ticks and Lyme disease — https://parks.canada.ca/lhn-nhs/qc/canallachine/securite-safety/terrestre-land/tiques-lyme-ticks", "notes": "Quebec callers can use Info-Santé at 811 for advice on preventive treatment after a tick bite.", "urls": ["https://parks.canada.ca/lhn-nhs/qc/canallachine/securite-safety/terrestre-land/tiques-lyme-ticks"]}, {"id": "13-026", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 26, "title": "Wash an animal bite for fifteen minutes and seek rabies shots the same day", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Soap, water, and an emergency visit.", "plain": "Any bite and scratch that breaks the skin from a bat, a raccoon, a fox, and a stray dog needs immediate washing with soap and running water for fifteen minutes. Then get to emergency care the same day for rabies shots — once symptoms start, rabies cannot be cured. Report the animal to local animal control so it can be found and tested.", "benefit_text": "Fifteen minutes of soap-and-water washing removes most of the virus from the wound; the same-day vaccine series given before symptoms appear prevents a disease that is otherwise fatal.", "sources": "Canadian Food Inspection Agency — rabies fact sheet — http://inspection.canada.ca/en/animal-health/terrestrial-animals/diseases/reportable/rabies/fact-sheet", "notes": "", "urls": ["http://inspection.canada.ca/en/animal-health/terrestrial-animals/diseases/reportable/rabies/fact-sheet"]}, {"id": "13-027", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 27, "title": "In a robbery, cooperate and be a good witness", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; self-control under threat.", "plain": "When someone demands your wallet and phone with threats, hand them over. Your life is worth more than anything you carry. Stay calm, do not chase the robber, and try to remember height, clothing, direction of flight, and anything distinctive. Call 911 as soon as it is safe and give the dispatcher every detail.", "benefit_text": "Cooperation ends most robberies without injury; a calm, detailed 911 report gives police the description that actually leads to arrests.", "sources": "York Regional Police — personal safety tips — http://www.yrp.ca/stay-safe/personal-safety", "notes": "Graded high on death because resisting a robbery is a classic trigger for lethal escalation; the value here is in not getting killed.", "urls": ["http://www.yrp.ca/stay-safe/personal-safety"]}, {"id": "13-028", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 28, "title": "After a risky exposure, ask emergency about HIV preventive pills within three days", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "An emergency visit and a month of pills.", "plain": "After unprotected sex with a partner whose HIV status is unknown, a broken condom, and a needlestick injury, emergency departments can prescribe a month of preventive pills — but only when started within three days of the exposure, and sooner is better. Go the same day, explain what happened, and take every pill for the full four weeks.", "benefit_text": "The 28-day preventive course started within 72 hours of exposure blocks the virus from taking hold; each day of delay lowers the protection.", "sources": "Public Health Agency of Canada — HIV biomedical prevention (PrEP and PEP) fact sheet — https://www.canada.ca/en/public-health/services/publications/diseases-conditions/hiv-factsheet-biomedical-prevention-prep-pep.html", "notes": "", "urls": ["https://www.canada.ca/en/public-health/services/publications/diseases-conditions/hiv-factsheet-biomedical-prevention-prep-pep.html"]}, {"id": "13-029", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 29, "title": "Never pull out an impaled object — stabilize it and call 911", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; bulky padding and stillness.", "plain": "A knife, a nail, and a branch stuck in the body may be plugging the bleeding. Leave it exactly where it is. Stabilize it with bulky padding and bandages so it cannot move, keep the person still, and call 911. Removing it outside an operating room can unleash bleeding you cannot stop.", "benefit_text": "Leaving the object in place tamponades damaged vessels until 911 brings surgical care; field removal is a classic cause of preventable death.", "sources": "IFRC — International First Aid, Resuscitation and Education Guidelines 2025 — https://www.ifrc.org/sites/default/files/2026-03/IFRC%20International%20First%20Aid,%20Resuscitation%20and%20Education%20Guidelines%202025.pdf", "notes": "", "urls": ["https://www.ifrc.org/sites/default/files/2026-03/IFRC%20International%20First%20Aid,%20Resuscitation%20and%20Education%20Guidelines%202025.pdf"]}, {"id": "13-030", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 30, "title": "Splint a broken bone where it lies and do not straighten it", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A rigid splint and padding from whatever is at hand.", "plain": "For a suspected fracture, keep the limb still in the position you found it. Pad a rigid splint — a magazine, a board, and a folded umbrella — alongside the break and tie it above and below the injury, including the joints on both sides. Do not try to straighten a bent limb. Apply ice wrapped in cloth and get to emergency care.", "benefit_text": "Splinting as found prevents a broken bone end from cutting vessels and nerves during transport; leaving a deformed limb alone avoids turning a closed fracture into an open one.", "sources": "IFRC — International First Aid, Resuscitation and Education Guidelines 2025 — https://www.ifrc.org/sites/default/files/2026-03/IFRC%20International%20First%20Aid,%20Resuscitation%20and%20Education%20Guidelines%202025.pdf", "notes": "", "urls": ["https://www.ifrc.org/sites/default/files/2026-03/IFRC%20International%20First%20Aid,%20Resuscitation%20and%20Education%20Guidelines%202025.pdf"]}, {"id": "13-031", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 31, "title": "Know that helping in an emergency will not get you sued for an honest mistake", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; knowing your rights.", "plain": "Ontario's Good Samaritan Act protects volunteers who give emergency first aid from lawsuits over honest mistakes; only gross negligence is excluded. Quebec's Charter goes further: it requires every person to come to the aid of anyone whose life is in peril, unless helping would endanger the helper and a third person, and unless there is another valid reason.", "benefit_text": "Ontario's 2001 Good Samaritan Act shields good-faith rescuers from ordinary-negligence claims, and Quebec's Charter of Human Rights and Freedoms (art. 2) frames rescue as a duty — so fear of liability should never freeze you.", "sources": "Good Samaritan Act, 2001, S.O. 2001, c. 2 — https://www.ontario.ca/laws/statute/01g02; Charter of Human Rights and Freedoms, CQLR c. C-12, art. 2 — https://www.legisquebec.gouv.qc.ca/fr/document/lc/C-12/20050617?langCont=en", "notes": "Statute wording paraphrased per the adaptation contract (no translated statutes); the Quebec article 2 duty is quoted from the official English text.", "urls": ["https://www.legisquebec.gouv.qc.ca/fr/document/lc/C-12/20050617?langCont=en", "https://www.ontario.ca/laws/statute/01g02;"]}, {"id": "13-032", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 32, "title": "Call and text 988 when you and someone you love is in suicide crisis", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a call and staying close.", "plain": "When you and someone you love is thinking about suicide and self-harm, call and text the national crisis line. Trained counsellors answer in English and French, day and night, every day of the year. Stay with the person, remove means of harm where you safely can, and call 911 when danger is immediate.", "benefit_text": "The 988 Suicide Crisis Helpline — call and text, English and French, 24 hours a day, 7 days a week — connects a person in crisis to a trained counsellor within minutes; calling 911 alongside it brings in-person help when danger is immediate.", "sources": "Government of Canada — 9-8-8 Suicide Crisis Helpline launch — https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html", "notes": "", "urls": ["https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html"]}, {"id": "13-033", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 33, "title": "Call 811 for free health advice before driving to emergency", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a phone call.", "plain": "Ontario's Health811 and Quebec's 811 line connect you to a registered nurse any hour of the day and night for free, confidential advice on whether a symptom needs emergency care, a clinic visit, and home care. Quebec's line also offers social-service help and a family-doctor finder through its menu options. Use it for non-urgent questions; call 911 for anything that cannot wait.", "benefit_text": "Ontario Health811 and Quebec's 811 (Info-Santé) give free nurse advice 24 hours a day, 7 days a week, in more than 200 languages in Ontario; the right call to 811 instead of 911 keeps emergency lines free for true emergencies.", "sources": "Ontario Health811 — https://health811.ontario.ca; Quebec 811 (Info-Santé / Info-Social) — https://www.ciusss-capitalenationale.gouv.qc.ca/en/services/urgence/811", "notes": "Quebec's 811 menu: option 1 Info-Santé, option 2 Info-Social, option 3 family-doctor finder (GAP). TTY numbers conflicted across sources and are not printed.", "urls": ["https://health811.ontario.ca;", "https://www.ciusss-capitalenationale.gouv.qc.ca/en/services/urgence/811"]}, {"id": "13-034", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 34, "title": "Keep a battery radio and heed Alert Ready warnings", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A battery and crank radio; no subscription.", "plain": "Canada's Alert Ready system pushes emergency alerts to TV, radio, and cell phones for tornadoes, floods, wildfires, and Amber Alerts. You cannot opt out of the wireless alerts — when your phone sounds, read the message and follow the instructions at once. A battery and crank radio keeps you informed when the power and cell networks fail.", "benefit_text": "Alert Ready broadcast more than 895 alerts in 2025; a phone that cannot be silenced for these warnings, plus a battery radio, means you hear the evacuation order even during a blackout.", "sources": "Alert Ready — https://www.alertready.ca/", "notes": "", "urls": ["https://www.alertready.ca/"]}, {"id": "13-035", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 35, "title": "Learn the three levels of Environment Canada weather alerts", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a glance at the forecast page.", "plain": "Environment Canada issues weather alerts in three levels: a watch means conditions are favourable and you should get ready; an advisory means significant weather is happening and you should act now; a warning means severe weather is happening and you should act now. Check the alert level before travelling and change plans when a warning covers your route.", "benefit_text": "Knowing that a watch means get ready while a warning means act now turns a forecast into a decision — especially for tornadoes and blizzards where minutes matter.", "sources": "Environment and Climate Change Canada — weather alerts explained — https://www.canada.ca/en/services/environment/weather/severeweather/weather-alerts.html", "notes": "", "urls": ["https://www.canada.ca/en/services/environment/weather/severeweather/weather-alerts.html"]}, {"id": "13-036", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 36, "title": "Report wildfires to the provincial line — 911 only for immediate danger", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a phone call.", "plain": "In British Columbia, call the provincial wildfire reporting line — star on a cell phone works too; in Quebec, call SOPFEU's forest-fire line. Call 911 only when people and buildings are in immediate danger. Never assume someone else has already called.", "benefit_text": "British Columbia: 1-800-663-5555, and *5555 on a cell phone; Quebec SOPFEU: 1-800-463-3389. Early reports put crews on a fire while it is still small; 911 stays reserved for immediate threats to people and homes.", "sources": "B.C. wildfire contact channels — https://www2.gov.bc.ca/gov/content/safety/wildfire-status/contact-channels; SOPFEU — signaler un feu — https://www.sopfeu.qc.ca/signaler-un-feu/", "notes": "", "urls": ["https://www.sopfeu.qc.ca/signaler-un-feu/", "https://www2.gov.bc.ca/gov/content/safety/wildfire-status/contact-channels;"]}, {"id": "13-037", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 37, "title": "When a winter storm traps your car, stay in the vehicle", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A winter car kit assembled in autumn.", "plain": "When a blizzard traps your car, stay inside it — the vehicle is your shelter, and it is far easier for rescuers to find than a person on foot. Keep the tailpipe clear of snow so exhaust cannot poison the cabin, run the engine in short bursts for heat, and make yourself visible with hazard lights and a bright cloth on the antenna. Keep a winter car kit with blankets, food, water, and a shovel.", "benefit_text": "Staying with the vehicle and keeping the tailpipe clear prevents the two classic killers of stranded motorists: freezing and carbon monoxide poisoning.", "sources": "Get Prepared — how to prepare for winter storms — https://www.canada.ca/en/services/policing/emergencies/preparedness/get-prepared/hazards-emergencies/winter-storms/how-prepare.html; Get Prepared — car emergency kit list — https://www.canada.ca/en/services/policing/emergencies/preparedness/get-prepared/emergency-kits/car-kit.html", "notes": "", "urls": ["https://www.canada.ca/en/services/policing/emergencies/preparedness/get-prepared/emergency-kits/car-kit.html", "https://www.canada.ca/en/services/policing/emergencies/preparedness/get-prepared/hazards-emergencies/winter-storms/how-prepare.html;"]}, {"id": "13-038", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 38, "title": "In an earthquake, drop, cover, and hold on", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; practice once at home.", "plain": "When shaking starts, drop to the ground, take cover under a sturdy table and desk, and hold on until the shaking stops. Stay away from windows, glass, and anything that can fall. When you are in bed, stay there and cover your head with a pillow. Do not run outside during the shaking, and do not use elevators after it.", "benefit_text": "Drop, cover, and hold on protects against the falling objects that cause most earthquake injuries; staying inside avoids the shower of glass at building exits.", "sources": "FEMA — earthquakes — https://www.ready.gov/earthquakes", "notes": "", "urls": ["https://www.ready.gov/earthquakes"]}, {"id": "13-039", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 39, "title": "In bear country, never run — back away slowly and talk calmly", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; bear spray for the trail.", "plain": "When you meet a bear, do not run: running can trigger a chase. Stand your ground, talk in a calm voice, and back away slowly while facing the bear. Make yourself look big, keep children close, and give the bear a clear escape route. Carry bear spray where bears live and learn how to use it before the trip.", "benefit_text": "Backing away slowly while talking calmly defuses most encounters; running is the behaviour most linked to a bear charging.", "sources": "Parks Canada — bears and human safety — https://parks.canada.ca/agence-agency/bib-lib/politiques-policies/science/nature/nature03", "notes": "", "urls": ["https://parks.canada.ca/agence-agency/bib-lib/politiques-policies/science/nature/nature03"]}, {"id": "13-040", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 40, "title": "Build a 72-hour emergency kit before you need it", "money": "low", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "A weekend of shopping and packing; rotate food and water yearly.", "plain": "Pack a kit that lets your household live for three days with no power and no stores open: two litres of water per person per day, non-perishable food with a manual can opener, a flashlight and radio with batteries, a first aid kit, cash in small bills, extra keys, a phone charger, medications, and a copy of your emergency plan.", "benefit_text": "The federal Get Prepared guide sets 72 hours as the minimum self-sufficiency window, with 2 litres of water per person per day; a packed kit turns the first chaotic hours of any disaster into a routine.", "sources": "Get Prepared — build an emergency kit — https://www.canada.ca/en/services/policing/emergencies/preparedness/get-prepared/emergency-kits/get-kit.html", "notes": "", "urls": ["https://www.canada.ca/en/services/policing/emergencies/preparedness/get-prepared/emergency-kits/get-kit.html"]}, {"id": "13-041", "chapter_num": 13, "chapter_title": "Emergencies: what to do first", "chapter_file": "13-emergencies.md", "number": 41, "title": "Take a first aid and CPR course and renew it every three years", "money": "low", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A weekend course; renewal before expiry.", "plain": "A weekend first aid and CPR course teaches compressions, choking rescue, bleeding control, and auto-injector use with hands-on practice. Certification lasts three years; renew before it lapses so your skills stay current. Courses run through the Red Cross, St. John Ambulance, and local community centres across Canada.", "benefit_text": "Training converts the earlier items in this chapter from reading into reflexes; a current three-year certification means your compressions and choking rescues work when they count.", "sources": "Canadian Red Cross — Standard First Aid and CPR — https://www.redcross.ca/training-and-certification/course-descriptions/first-aid-training/standard-first-aid-cpr", "notes": "Course prices vary by provider and were not verified from a primary source, so none is printed.", "urls": ["https://www.redcross.ca/training-and-certification/course-descriptions/first-aid-training/standard-first-aid-cpr"]}, {"id": "14-001", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 1, "title": "Turn on multi-factor authentication everywhere it is offered", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a few minutes per account.", "plain": "Add a second factor — an authenticator app and a hardware key — to email, banking, and every account that holds money and personal data. Text-message codes are better than nothing but weaker than app codes. When a service offers passkeys, take them: they cannot be phished.", "benefit_text": "MFA blocks 100% of automated bot attacks, 96% of bulk phishing, and 76% of targeted attacks (Google 2019, via Get Cyber Safe); one setup per account, protection for years.", "sources": "Get Cyber Safe — multi-factor authentication — https://www.getcybersafe.gc.ca/en/resources/multi-factor-authentication", "notes": "", "urls": ["https://www.getcybersafe.gc.ca/en/resources/multi-factor-authentication"]}, {"id": "14-002", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 2, "title": "Give every important account its own long passphrase, kept in a password manager", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing for most managers; an afternoon to switch accounts over.", "plain": "Use a unique passphrase of four and more random words, fifteen characters and longer, for every important account — never reuse one across sites. A password manager generates, stores, and fills these for you so you only memorize the one master passphrase. Write the master passphrase on paper kept at home, not in a file on the computer.", "benefit_text": "Four-plus random words at 15+ characters resist cracking far longer than a short complex password; a manager makes a unique login for every site effortless.", "sources": "Get Cyber Safe — strong passphrases — https://www.getcybersafe.gc.ca/en/cyber-security-all-stars-trading-cards; Get Cyber Safe — ensure your accounts are secure — https://www.getcybersafe.gc.ca/en/blogs/ensure-your-accounts-are-secure", "notes": "", "urls": ["https://www.getcybersafe.gc.ca/en/blogs/ensure-your-accounts-are-secure", "https://www.getcybersafe.gc.ca/en/cyber-security-all-stars-trading-cards;"]}, {"id": "14-003", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 3, "title": "Lock your devices and act fast when one goes missing", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; settings and a quick call.", "plain": "Set a short auto-lock with a PIN and biometrics on every phone, tablet, and laptop. When a device goes missing, use its find feature to lock and erase it remotely, call your carrier to deactivate the line and blacklist the device, and report the loss to local police with the serial number.", "benefit_text": "A locked screen buys the hours needed to wipe remotely; deactivating with the carrier plus a police report blocks the thief from your accounts and your number.", "sources": "Get Cyber Safe — secure your phones and tablets — https://www.getcybersafe.gc.ca/en/secure-your-devices/phones-and-tablets", "notes": "", "urls": ["https://www.getcybersafe.gc.ca/en/secure-your-devices/phones-and-tablets"]}, {"id": "14-004", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 4, "title": "Report card fraud to your issuer at once, then to police and the Anti-Fraud Centre", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a phone call and an online report.", "plain": "When you spot a charge you did not make, call the number on the back of the card immediately — the issuer freezes the card and starts the investigation. Then report to local police and to the Canadian Anti-Fraud Centre. For identity fraud, also place alerts with Equifax Canada and TransUnion Canada. Know the trap: the Anti-Fraud Centre collects intelligence and does not investigate cases and does not recover money — anyone promising to recover your funds for a fee is running a second scam.", "benefit_text": "Federal rules cap your credit-card liability at $50 for unauthorized use, and debit losses beyond your control come back to you; reporting to the issuer, police, and the CAFC (1-888-495-8501) starts all three tracks at once.", "sources": "Financial Consumer Agency of Canada — fraud and FCAC oversight of unauthorized transactions — https://www.canada.ca/en/financial-consumer-agency/corporate/transparency/briefing-packages-parliamentary-committee-appearances/standing-committee-finance-may-31-2024/fraud-fcac-oversight-authorized-transactions.html; Canadian Anti-Fraud Centre — impersonation warning — https://www.cacp.ca/_Library/Alert_Documents/2025_06_05_CAFC_Impersonation_-_EN.pdf", "notes": "The CAFC never asks for your SIN, verification codes, remote access, or payment, and never promises to recover funds. Unlike some countries' anti-fraud centres, it does not investigate individual cases.", "urls": ["https://www.cacp.ca/_Library/Alert_Documents/2025_06_05_CAFC_Impersonation_-_EN.pdf", "https://www.canada.ca/en/financial-consumer-agency/corporate/transparency/briefing-packages-parliamentary-committee-appearances/standing-committee-finance-may-31-2024/fraud-fcac-oversight-authorized-transactions.html;"]}, {"id": "14-005", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 5, "title": "Report spam and scams through the official online form", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; minutes to file a report.", "plain": "Do not click links in unexpected texts and emails. Report spam through the Spam Reporting Centre's online form so investigators see the pattern; delete the message after reporting. For phone scams, hang up and report the number the same way.", "benefit_text": "Each report feeds the CRTC's enforcement picture; reporting takes minutes and helps shut down the campaigns targeting Canadians.", "sources": "Canada's Anti-Spam Legislation — Spam Reporting Centre — https://ised-isde.canada.ca/site/canada-anti-spam-legislation/en/form/report-spam-form", "notes": "", "urls": ["https://ised-isde.canada.ca/site/canada-anti-spam-legislation/en/form/report-spam-form"]}, {"id": "14-006", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 6, "title": "Treat every CRA demand for gift cards as a scam", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; hanging up.", "plain": "The Canada Revenue Agency never asks for personal information by email and text, and never demands payment by gift card, bitcoin, and e-transfer. A caller threatening arrest over unpaid tax is a criminal, not an officer. Hang up, do not call back, and report the attempt to the Canadian Anti-Fraud Centre. When you already paid, report to local police as well.", "benefit_text": "CRA-impersonation scams are among the most reported frauds in Canada; hanging up costs nothing, while one gift-card payment is gone forever.", "sources": "RCMP — beware fraudulent communications appearing to be from the Canada Revenue Agency — https://rcmp.ca/en/bc/safety-tips/frauds-and-scams/beware-fraudulent-communications-appear-be-canada-revenue-agency", "notes": "", "urls": ["https://rcmp.ca/en/bc/safety-tips/frauds-and-scams/beware-fraudulent-communications-appear-be-canada-revenue-agency"]}, {"id": "14-007", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 7, "title": "Review signed-in sessions and connected devices twice a year", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a short settings review.", "plain": "Open the security settings of your email, bank, and social accounts twice a year and sign out every session and device you do not recognize. Remove old app connections you no longer use. Turn on login alerts so the next unknown sign-in reaches you at once.", "benefit_text": "A twice-yearly review evicts the forgotten sessions attackers reuse; login alerts turn the next breach attempt into a warning you actually see.", "sources": "Get Cyber Safe — ensure your accounts are secure — https://www.getcybersafe.gc.ca/en/blogs/ensure-your-accounts-are-secure", "notes": "", "urls": ["https://www.getcybersafe.gc.ca/en/blogs/ensure-your-accounts-are-secure"]}, {"id": "14-008", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 8, "title": "Give apps the minimum permissions they need", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a yearly pass through phone settings.", "plain": "When installing an app, deny location, contacts, microphone, and camera access unless the app's core job needs it. Review permissions yearly in your phone settings and revoke what the app never uses. Prefer the mobile website for services you rarely open.", "benefit_text": "Minimum permissions shrink what a breached and sold app can take; a yearly review takes minutes and closes silent data drains.", "sources": "Get Cyber Safe — secure your phones and tablets — https://www.getcybersafe.gc.ca/en/secure-your-devices/phones-and-tablets", "notes": "", "urls": ["https://www.getcybersafe.gc.ca/en/secure-your-devices/phones-and-tablets"]}, {"id": "14-009", "chapter_num": 14, "chapter_title": "Accounts and Information Security", "chapter_file": "14-accounts-and-infosec.md", "number": 9, "title": "Use your PIPEDA right to see and correct your personal data", "money": "0", "time": "mid", "willpower": "no", "benefit": "low", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a written request.", "plain": "Any private company doing business in Canada must tell you what personal data it holds about you and let you ask for corrections. Write to the company's privacy officer with your request; the company must answer within thirty days. When it refuses, it must explain why in writing, and you can complain to the Privacy Commissioner of Canada.", "benefit_text": "The access right under PIPEDA forces companies to show their file on you within 30 days; a complaint to the OPC (1-800-282-1376) backs you up when they refuse.", "sources": "Office of the Privacy Commissioner of Canada — businesses and your personal information — https://www.priv.gc.ca/en/privacy-topics/information-and-advice-for-individuals/your-privacy-rights/businesses-and-your-personal-information", "notes": "Refusals must be in writing with reasons; the OPC's information line is 1-800-282-1376.", "urls": ["https://www.priv.gc.ca/en/privacy-topics/information-and-advice-for-individuals/your-privacy-rights/businesses-and-your-personal-information"]}, {"id": "15-001", "chapter_num": 15, "chapter_title": "Renting and Buying a Home", "chapter_file": "15-renting-and-buying-a-home.md", "number": 1, "title": "In Ontario, pay only last month's rent upfront — never a damage deposit", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; it saves you money.", "plain": "An Ontario landlord can ask for a rent deposit of at most one month's rent, to be applied to the last month of the tenancy. Damage deposits, security deposits, key deposits, and pet deposits are prohibited. If a landlord demands more, that demand itself breaks the rules.", "benefit_text": "Keeps a full extra month of rent in your pocket at move-in; any deposit beyond one month's rent is unlawful and recoverable.", "sources": "Residential Tenancies Act, 2006, S.O. 2006, c. 17 — https://www.ontario.ca/laws/statute/06r17", "notes": "", "urls": ["https://www.ontario.ca/laws/statute/06r17"]}, {"id": "15-002", "chapter_num": 15, "chapter_title": "Renting and Buying a Home", "chapter_file": "15-renting-and-buying-a-home.md", "number": 2, "title": "In Quebec, the most a landlord can take in advance is the first month's rent", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; it saves you money.", "plain": "A Quebec landlord may ask for the first month's rent in advance and nothing else — no deposit for keys, no damage deposit, no extra months. The lease must be on the government's mandatory form, which states this rule on its face.", "benefit_text": "Same protection as Ontario with a different ceiling: one month, paid as rent, and nothing on top.", "sources": "Mandatory lease form, art. 1904 C.C.Q. — https://www.legisquebec.gouv.qc.ca/fr/ressource/rc/T-15.01R3_EN_002_003.pdf?langCont=en&cible=E3E0C0DF97E1F4EC8E7E87D9F8F1CDCB", "notes": "", "urls": ["https://www.legisquebec.gouv.qc.ca/fr/ressource/rc/T-15.01R3_EN_002_003.pdf?langCont=en&cible=E3E0C0DF97E1F4EC8E7E87D9F8F1CDCB"]}, {"id": "15-003", "chapter_num": 15, "chapter_title": "Renting and Buying a Home", "chapter_file": "15-renting-and-buying-a-home.md", "number": 3, "title": "Never accept a lockout: only the tribunal can end your tenancy", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "A call to the police and a tribunal application; no lawyer needed at first.", "plain": "A landlord who changes the locks, cuts utilities, threatens you, seizes your belongings to force you out is breaking the law. In Ontario a landlord can only recover a unit if you have vacated, if the Landlord and Tenant Board orders it, and may never seize your property without legal process. Document everything and call the police if you feel unsafe.", "benefit_text": "Self-help evictions are unlawful; the tribunal process buys you time, and the landlord faces orders and penalties instead.", "sources": "Residential Tenancies Act, ss.39-40 — https://www.ontario.ca/laws/statute/06r17", "notes": "", "urls": ["https://www.ontario.ca/laws/statute/06r17"]}, {"id": "15-004", "chapter_num": 15, "chapter_title": "Renting and Buying a Home", "chapter_file": "15-renting-and-buying-a-home.md", "number": 4, "title": "Check every rent increase against the guideline", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a few minutes of arithmetic.", "plain": "In Ontario most rent increases are capped at the annual provincial guideline and need proper written notice; an increase above the guideline needs tribunal approval. If your building was first occupied after the exemption date, the cap may not apply — check before you assume.", "benefit_text": "Ontario's 2026 guideline is 2.1%; any increase above the guideline without tribunal approval can be challenged and rolled back.", "sources": "Residential Tenancies Act — https://www.ontario.ca/laws/statute/06r17", "notes": "The 2026 guideline figure is per the Ontario government's published 2026 rate (secondary coverage; the regulation page was not fetched in this edition). Quebec uses the Tribunal administratif du logement's annual calculation method rather than a fixed guideline; the 2026 base figure is UNVERIFIED — see docs/verification/15-renting-and-buying-a-home.md.", "urls": ["https://www.ontario.ca/laws/statute/06r17"]}, {"id": "15-005", "chapter_num": 15, "chapter_title": "Renting and Buying a Home", "chapter_file": "15-renting-and-buying-a-home.md", "number": 5, "title": "Remember that a sale does not end your lease", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; knowing your rights.", "plain": "If your landlord sells the building, your tenancy continues with the new owner on the same terms. A new owner who wants the unit for themselves must go through the tribunal process with proper notice and compensation — they cannot simply tell you to leave.", "benefit_text": "Prevents panic moves and under-compensated departures when buildings change hands.", "sources": "Residential Tenancies Act — https://www.ontario.ca/laws/statute/06r17", "notes": "Quebec's buyer-move-in rules differ (notice periods under the Civil Code); the specifics are UNVERIFIED in this edition — see docs/verification/15-renting-and-buying-a-home.md.", "urls": ["https://www.ontario.ca/laws/statute/06r17"]}, {"id": "15-006", "chapter_num": 15, "chapter_title": "Renting and Buying a Home", "chapter_file": "15-renting-and-buying-a-home.md", "number": 6, "title": "Buying in Ontario: budget the land transfer tax and claim the first-time refund", "money": "low", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "The tax itself, paid on registration; the refund claim is paperwork.", "plain": "Ontario charges land transfer tax when the deed is registered, on top of the purchase price. First-time buyers who will live in the home can get a refund of up to four thousand dollars. Budget the tax before you fall in love with a listing, and file the refund claim with the transfer.", "benefit_text": "The first-time homebuyers' refund returns up to $4,000 of land transfer tax; missing the claim window leaves that money with the province.", "sources": "Land transfer tax refunds for first-time homebuyers — http://www.ontario.ca/document/land-transfer-tax/land-transfer-tax-refunds-first-time-homebuyers", "notes": "", "urls": ["http://www.ontario.ca/document/land-transfer-tax/land-transfer-tax-refunds-first-time-homebuyers"]}, {"id": "15-007", "chapter_num": 15, "chapter_title": "Renting and Buying a Home", "chapter_file": "15-renting-and-buying-a-home.md", "number": 7, "title": "Buying in Quebec: expect the notary and the welcome tax", "money": "low", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Notary fees and the transfer tax, both on top of the price.", "plain": "In Quebec the sale is completed before a notary, who registers the deed. After registration the municipality bills you the real-estate transfer tax — the \"welcome tax\" — on a sliding scale, with some cities charging higher rates on expensive properties. Ask the notary for the exact figure before closing day so it does not ambush your budget.", "benefit_text": "The 2026 base scale runs from half a percent on the first slice to one and a half percent above the top threshold, with cities like Quebec City charging up to three percent on high-value bands; budgeting it early avoids a painful surprise.", "sources": "Municipal transfer tax rules — https://mille-isles.ca/en/services/real-estate-transfer-tax/ ; Quebec City by-law R.V.Q. 3101 — https://reglements.ville.quebec.qc.ca/fr/pdf/rc/R.V.Q.3101.pdf", "notes": "Municipalities set their own rates above the base scale; confirm your city's current by-law with the notary.", "urls": ["https://mille-isles.ca/en/services/real-estate-transfer-tax/", "https://reglements.ville.quebec.qc.ca/fr/pdf/rc/R.V.Q.3101.pdf"]}]);
